import re

def check_month(m):
    if not re.fullmatch(r'\d{4}-\d{2}', m):
        raise ValueError('month must look like 2025-03')
    return m

print(check_month('2025-03'))
try:
    check_month('2025-3')
except ValueError as e:
    print(e)

