import sqlite3
import pandas as pd

conn = sqlite3.connect(":memory:")
conn.execute("CREATE TABLE sales (month TEXT, region TEXT, amount REAL, status TEXT)")
conn.executemany("INSERT INTO sales VALUES (?, ?, ?, ?)", [
    ("2025-01", "north", 100.0, "paid"), ("2025-01", "south", 60.0, "paid"), ("2025-01", "north", 40.0, "failed"),
    ("2025-02", "north", 80.0, "paid"), ("2025-02", "south", 90.0, "paid"), ("2025-02", "south", 20.0, "refunded"),
])

METRICS = {'revenue': 'SUM(amount)', 'orders': 'COUNT(*)'}

def report(conn, month, metric, status='paid'):
    if metric not in METRICS:
        raise ValueError('bad metric')
    sql = f'SELECT region, {METRICS[metric]} AS value FROM sales WHERE month = ? AND status = ? GROUP BY region ORDER BY region'
    df = pd.read_sql_query(sql, conn, params=(month, status))
    return df.to_csv(index=False, float_format='%.2f', lineterminator='\n')

print(report(conn, '2025-02', 'revenue'), end='')
print(report(conn, '2025-01', 'orders'), end='')
try:
    report(conn, '2025-01', 'profit')
except ValueError as e:
    print(e)
conn.close()

