CREATE OR REPLACE FUNCTION ra_total(p_month date)
RETURNS TABLE (region text, total numeric)
LANGUAGE sql AS $$
  SELECT s.region, SUM(s.amount) FROM ra_sales s
  WHERE s.sold_on >= p_month AND s.sold_on < p_month + INTERVAL '1 month'
  GROUP BY s.region ORDER BY s.region
$$;
